```python
import json
import re

MAX_BODY_BYTES = 16 * 1024

class BadRequest(ValueError):
    pass

class PayloadTooLarge(BadRequest):
    pass


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate JSON key")
        result[key] = value
    return result


def _reject_constant(value):
    # Reject non-JSON extensions such as NaN and Infinity.
    raise ValueError("Invalid JSON constant")


def validate_body(raw: bytes) -> dict:
    if len(raw) > MAX_BODY_BYTES:
        raise PayloadTooLarge("Request body is too large")

    try:
        body = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=_unique_object,
            parse_constant=_reject_constant,
        )
    except (UnicodeDecodeError, ValueError, RecursionError):
        raise BadRequest("Request body must be valid JSON") from None

    if not isinstance(body, dict):
        raise BadRequest("Request body must be an object")

    if set(body) != {"item_id", "quantity"}:
        raise BadRequest("Expected item_id and quantity only")

    item_id = body["item_id"]
    if not isinstance(item_id, str) or not re.fullmatch(
        r"[A-Za-z0-9_-]{1,64}", item_id
    ):
        raise BadRequest("item_id has an invalid format")

    quantity = body["quantity"]
    # bool is a subclass of int in Python; reject it explicitly.
    if type(quantity) is not int or not 1 <= quantity <= 100:
        raise BadRequest("quantity must be an integer from 1 to 100")

    return {"item_id": item_id, "quantity": quantity}
```

